import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{@Test void deletionPoliciesAndScheduleLifecycle(){Object s=TaskBinding.create();if(TaskBinding.deletionPolicy().equals("cascade")){TaskBinding.deleteSubject(s);assertFalse(TaskBinding.subjects(s).containsKey("s1"));assertEquals(Set.of(),TaskBinding.teacherIds(s,"t1"));}else{assertEquals("reject",TaskBinding.deletionPolicy());assertThrows(IllegalStateException.class,()->TaskBinding.deleteSubject(s));assertTrue(TaskBinding.subjects(s).containsKey("s1"));assertEquals(Set.of("l1","l3"),TaskBinding.teacherIds(s,"t1"));}Object t=TaskBinding.create();if(TaskBinding.deletionPolicy().equals("cascade")){TaskBinding.deleteTeacher(t);assertFalse(TaskBinding.teachers(t).containsKey("t1"));assertEquals(Set.of(),TaskBinding.teacherIds(t,"t1"));}else{assertThrows(IllegalStateException.class,()->TaskBinding.deleteTeacher(t));assertTrue(TaskBinding.teachers(t).containsKey("t1"));}TaskBinding.deleteSchedule(t);assertEquals(Set.of(),TaskBinding.groupIds(t,"g1"));assertEquals(Set.of(),TaskBinding.groupIds(t,"g2"));TaskBinding.recreate(t);assertEquals(Set.of(),TaskBinding.groupIds(t,"g1"));} @Test void twoSpecializationsWithChosenPolicy(){Object school=TaskBinding.school();assertEquals(TaskBinding.schoolLimit(),TaskBinding.classSize(school));assertTrue(TaskBinding.schoolValid(school));TaskBinding.extra(school);assertFalse(TaskBinding.schoolValid(school));Object driving=TaskBinding.driving();assertTrue(TaskBinding.car(driving,"c1"));assertFalse(TaskBinding.car(driving,"unknown"));assertEquals(2,TaskBinding.theory(driving));assertEquals(1,TaskBinding.practice(driving));}}
